// S3 trial module parity: worker/src/trial/s3.ts, replayed on real daily candles (committed Coinbase fixtures), must
// reproduce the research implementation EXACTLY (golden file generated by engine/src/research/select/alloc.mjs on
// research/strategy-select): every order (time, side, quantity, notional, feasibility), the daily equity, and fees.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { buildSync } from "esbuild";

const HERE = dirname(fileURLToPath(import.meta.url));
const OUT = join(mkdtempSync(join(tmpdir(), "alpha-s3-")), "s3.mjs");
buildSync({ entryPoints: [join(HERE, "..", "src", "trial", "s3.ts")], bundle: true, format: "esm", platform: "neutral", outfile: OUT, logLevel: "silent" });
const M = await import(pathToFileURL(OUT).href);
const G = JSON.parse(readFileSync(join(HERE, "fixtures", "s3-golden.json"), "utf8"));
const K = { BTC: JSON.parse(readFileSync(join(HERE, "fixtures", "BTC-USD-1d-coinbase.json"), "utf8")).candles, ETH: JSON.parse(readFileSync(join(HERE, "fixtures", "ETH-USD-1d-coinbase.json"), "utf8")).candles };
const near = (a, b) => Math.abs(a - b) <= 1e-9 * Math.max(1, Math.abs(b));

describe("S3 parity: trial module == research backtest (BTC + ETH, $50 sleeves, 0.20% + 0.05%, today's minimums)", () => {
  for (const asset of ["BTC", "ETH"]) {
    it(`${asset}: identical orders, daily equity, fees and final equity`, () => {
      const g = G.sleeves[asset];
      const r = M.replaySleeve(K[asset], asset, { fromMs: Date.parse(G.window[0]), toMs: Date.parse(G.window[1]), capital: G.capitalPerSleeve, minUsd: g.minUsd });
      assert.ok(g.orders.length > 20, "precondition: a meaningful number of orders");
      assert.equal(r.orders.length, g.orders.length, "order count");
      g.orders.forEach((e, i) => {
        const u = r.orders[i];
        assert.equal(u.t, e.t, `order ${i} time`); assert.equal(u.side, e.side, `order ${i} side`);
        assert.ok(near(u.qty, e.qty) && near(u.notional, e.notional), `order ${i} qty/notional`);
        assert.equal(u.feasible, e.feasible, `order ${i} feasibility`); assert.equal(u.skipped, e.skipped, `order ${i} skipped`);
      });
      assert.equal(r.curve.length, g.curve.length, "equity days");
      g.curve.forEach(([t, eq], i) => { assert.equal(r.curve[i][0], t); assert.ok(near(r.curve[i][1], eq), `equity ${new Date(t).toISOString().slice(0, 10)}`); });
      assert.ok(near(r.fees, g.fees), "fees"); assert.ok(near(r.final, g.final), `final ${r.final} vs ${g.final}`);
    });
  }
  it("frozen settings: SMA 200, 30-day vol, 40% target, 0.10 band, 0.20% + 0.05%, $100, long only, no leverage", () => {
    const p = M.PARAMS;
    assert.deepEqual({ sma: p.sma, volDays: p.volDays, volTarget: p.volTarget, band: p.band, feePct: p.feePct, slipPct: p.slipPct, start: p.startEquityUsd, short: p.short, leverage: p.leverage },
      { sma: 200, volDays: 30, volTarget: 0.4, band: 0.1, feePct: 0.2, slipPct: 0.05, start: 100, short: false, leverage: false });
    assert.ok(Object.isFrozen(p) && Object.isFrozen(p.assets) && Object.isFrozen(p.assets.BTC));
  });
  it("no lookahead: the target at day i is unchanged by any later candle", () => {
    const base = K.BTC.slice(0, 900), altered = [...base.slice(0, 700), ...base.slice(700).map((k) => ({ ...k, c: k.c * 0.3, o: k.o * 0.3, h: k.h * 0.3, l: k.l * 0.3 }))];
    for (let i = 200; i < 700; i += 37) assert.equal(M.targetWeight(base, i), M.targetWeight(altered, i));
  });
  it("order rules: entering and leaving always trade; small re-sizes below the band do not; a full exit below the minimum is still allowed", () => {
    assert.equal(M.wantsOrder(0.5, 0, 0), true);
    assert.equal(M.wantsOrder(0, 0.5, 0.5), true);
    assert.equal(M.wantsOrder(0.55, 0.5, 0.5), false);
    assert.equal(M.wantsOrder(0.65, 0.5, 0.5), true);
    assert.equal(M.feasible(0.00001, 1, true, M.PARAMS.assets.BTC, 3.85), false, "below the coin minimum: even an exit cannot trade (recorded, retried)");
    assert.equal(M.feasible(0.0001, 2, true, M.PARAMS.assets.BTC, 3.85), true, "full exit below the USD minimum: allowed");
    assert.equal(M.feasible(0.0001, 2, false, M.PARAMS.assets.BTC, 3.85), false, "partial re-size below the USD minimum: skipped");
  });
});
